import os
import requests

def write_structured_log(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.getenv("DD_API_KEY")
    site = config.get("site", "datadoghq.com")
    url = f"https://http-intake.logs.{site}/v1/input/{api_key}"
    headers = {"Content-Type": "application/json"}
    response = requests.post(url, json=payload, headers=headers)
    result = {"status_code": response.status_code, "response": response.text}
    return result
